#define DSM_MAX_BODY (8U * 1024U * 1024U)
#define DSM_MAX_OUTPUT (8U * 1024U * 1024U)
#define LIT(text) text, sizeof(text) - 1

typedef struct {
    dsm_model model;
    dsm_tokenizer *tokenizer;
    dsm_forward *forward;
    dsm_metal *metal;
    float *logits;
    int32_t *cached;
    size_t cached_len, cached_cap;
    char model_id[256];
    uint32_t context;
    uint32_t threads;
    int use_metal;
} server;
typedef struct { char *data; size_t len, cap; } string;

static double now(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec + t.tv_nsec / 1e9; }
static int send_all(int fd, const void *buf, size_t len) { const char *p = buf; while (len) { ssize_t n = send(fd, p, len, 0); if (n <= 0) return 0; p += n; len -= (size_t)n; } return 1; }
static int append(string *s, const char *p, size_t n) { if (s->len + n + 1 > s->cap) { size_t cap = s->cap ? s->cap : 256; while (cap < s->len + n + 1) cap *= 2; char *data = realloc(s->data, cap); if (!data) return 0; s->data = data; s->cap = cap; } if (p && n) memcpy(s->data + s->len, p, n); s->len += n; s->data[s->len] = '\0'; return 1; }
static int appendf(string *s, const char *format, ...) { va_list args; va_start(args, format); va_list copy; va_copy(copy, args); int n = vsnprintf(NULL, 0, format, copy); va_end(copy); if (n < 0 || !append(s, NULL, (size_t)n)) { va_end(args); return 0; } vsnprintf(s->data + s->len - (size_t)n, (size_t)n + 1, format, args); va_end(args); return 1; }
static int json_string(string *out, const char *text) { if (!append(out, "\"", 1)) return 0; for (; *text; ++text) { unsigned char c = (unsigned char)*text; if (c == '"' || c == '\\') { if (!append(out, "\\", 1) || !append(out, text, 1)) return 0; } else if (c == '\n') { if (!append(out, "\\n", 2)) return 0; } else if (c == '\r') { if (!append(out, "\\r", 2)) return 0; } else if (c == '\t') { if (!append(out, "\\t", 2)) return 0; } else if (c < 0x20) { if (!appendf(out, "\\u%04x", c)) return 0; } else if (!append(out, text, 1)) return 0; } return append(out, "\"", 1); }
static int response(int fd, int status, const char *type, const char *body) { const char *reason = status == 200 ? "OK" : status == 400 ? "Bad Request" : status == 404 ? "Not Found" : status == 413 ? "Payload Too Large" : "Internal Server Error"; char header[512]; int n = snprintf(header, sizeof(header), "HTTP/1.1 %d %s\r\nContent-Type: %s\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n", status, reason, type, strlen(body)); return n > 0 && send_all(fd, header, (size_t)n) && send_all(fd, body, strlen(body)); }
static void error_response(int fd, int status, const char *message) { string body = {0}; append(&body, LIT("{\"error\":{\"message\":")); json_string(&body, message); append(&body, LIT(",\"type\":\"invalid_request_error\"}}")); response(fd, status, "application/json", body.data); free(body.data); }
static int token_text(const dsm_tokenizer *tokenizer, int32_t id, string *out) { FILE *file = tmpfile(); if (!file) return 0; int ok = dsm_token_decode(tokenizer, id, file); if (ok && fseek(file, 0, SEEK_END) == 0) { long n = ftell(file); if (n >= 0 && fseek(file, 0, SEEK_SET) == 0) { char *buf = n ? malloc((size_t)n) : NULL; if ((!n || buf) && (!n || fread(buf, 1, (size_t)n, file) == (size_t)n)) ok = append(out, buf, (size_t)n); else ok = 0; free(buf); } else ok = 0; } else ok = 0; fclose(file); return ok; }
static size_t utf8_complete(const char *s, size_t n) { if (!n) return 0; size_t p = n; while (p && ((unsigned char)s[p - 1] & 0xc0) == 0x80) --p; if (p == n) return n; unsigned char c = (unsigned char)s[p - 1]; size_t need = c < 0x80 ? 1 : c < 0xe0 ? 2 : c < 0xf0 ? 3 : 4; return n - (p - 1) >= need ? n : p - 1; }
static size_t stop_at(const char *text, char **stops, size_t count) { if (!strcmp(text, "<|im_end|>")) return 0; size_t best = SIZE_MAX; for (size_t i = 0; i < count; ++i) { char *at = *stops[i] ? strstr(text, stops[i]) : NULL; if (at && (size_t)(at - text) < best) best = (size_t)(at - text); } return best; }
static int parse_content(const dsm_json *content, string *out) { if (!content) return 0; if (content->type == DSM_JSON_STRING) { char *text = dsm_json_string_dup(content); int ok = text && append(out, text, strlen(text)); free(text); return ok; } if (content->type != DSM_JSON_ARRAY) return 0; for (size_t i = 0; i < content->count; ++i) { const dsm_json *part = content->items[i]; const dsm_json *type = dsm_json_object_get(part, "type"); const dsm_json *text = dsm_json_object_get(part, "text"); if (!type || !text || type->type != DSM_JSON_STRING || type->len != 4 || memcmp(type->text, "text", 4) || !parse_content(text, out)) return 0; } return 1; }
static int make_prompt(const dsm_json *root, string *prompt) { const dsm_json *messages = dsm_json_object_get(root, "messages"); if (!messages || messages->type != DSM_JSON_ARRAY) return 0; for (size_t i = 0; i < messages->count; ++i) { const dsm_json *message = messages->items[i]; const dsm_json *role = dsm_json_object_get(message, "role"); const dsm_json *content = dsm_json_object_get(message, "content"); int known_role = role && role->type == DSM_JSON_STRING && ((role->len == 6 && !memcmp(role->text, "system", 6)) || (role->len == 4 && !memcmp(role->text, "user", 4)) || (role->len == 9 && !memcmp(role->text, "assistant", 9))); if (!known_role || !content) return 0; char *role_text = dsm_json_string_dup(role); if (!role_text || !append(prompt, LIT("<|im_start|>")) || !append(prompt, role_text, strlen(role_text)) || !append(prompt, LIT("\n")) || !parse_content(content, prompt) || !append(prompt, LIT("<|im_end|>\n"))) { free(role_text); return 0; } free(role_text); } return append(prompt, LIT("<|im_start|>assistant\n")); }
static size_t common_prefix(const int32_t *a, size_t an, const int32_t *b, size_t bn) { size_t n = an < bn ? an : bn, i = 0; while (i < n && a[i] == b[i]) ++i; return i; }
static int cache_tokens(server *s, const dsm_tokens *tokens, const int32_t *generated, size_t generated_len) { size_t n = tokens->len + generated_len; if (n > s->cached_cap) { int32_t *cache = realloc(s->cached, n * sizeof(*cache)); if (!cache) return 0; s->cached = cache; s->cached_cap = n; } memcpy(s->cached, tokens->ids, tokens->len * sizeof(*s->cached)); if (generated_len) memcpy(s->cached + tokens->len, generated, generated_len * sizeof(*s->cached)); s->cached_len = n; return 1; }
static int sse_chunk(int fd, const char *id, const char *content, const char *finish) { string out = {0}; if (!append(&out, LIT("data: {\"id\":\"")) || !append(&out, id, strlen(id)) || !append(&out, LIT("\",\"object\":\"chat.completion.chunk\",\"choices\":[{\"index\":0,\"delta\":{"))) goto bad; if (content) { if (!append(&out, LIT("\"content\":")) || !json_string(&out, content)) goto bad; } if (!append(&out, LIT("},\"finish_reason\":"))) goto bad; if (finish) { if (!json_string(&out, finish)) goto bad; } else if (!append(&out, LIT("null"))) goto bad; if (!append(&out, LIT("}]}\n\n"))) goto bad; int ok = send_all(fd, out.data, out.len); free(out.data); return ok; bad: free(out.data); return 0; }
static int generate(server *s, int fd, const dsm_json *root) {
    string prompt = {0}, output = {0}, pending = {0}; dsm_tokens tokens = {0}; int32_t *generated = NULL; size_t generated_len = 0, generated_cap = 0, reused = 0; char **stops = NULL; size_t stop_count = 0;
    const dsm_json *v = dsm_json_object_get(root, "max_completion_tokens"); if (!v) v = dsm_json_object_get(root, "max_tokens"); int max_tokens = v && v->type == DSM_JSON_NUMBER ? (int)v->number : 16; const dsm_json *temp_v = dsm_json_object_get(root, "temperature"), *top_p_v = dsm_json_object_get(root, "top_p"), *stream_v = dsm_json_object_get(root, "stream"), *stop_v = dsm_json_object_get(root, "stop"); float temp = temp_v && temp_v->type == DSM_JSON_NUMBER ? (float)temp_v->number : 1.0f; float top_p = top_p_v && top_p_v->type == DSM_JSON_NUMBER ? (float)top_p_v->number : 1.0f; int stream = stream_v && stream_v->type == DSM_JSON_BOOL && stream_v->boolean;
    if (max_tokens < 0 || !make_prompt(root, &prompt) || !dsm_tokenize(s->tokenizer, prompt.data, 0, &tokens) || tokens.len + (size_t)max_tokens > s->context) { error_response(fd, 400, "invalid messages or context length"); goto done; }
    if (stop_v) { if (stop_v->type == DSM_JSON_STRING) stop_count = 1; else if (stop_v->type == DSM_JSON_ARRAY) stop_count = stop_v->count; else { error_response(fd, 400, "stop must be a string or array"); goto done; } stops = calloc(stop_count, sizeof(*stops)); if (!stops) goto done; for (size_t i = 0; i < stop_count; ++i) { stops[i] = dsm_json_string_dup(stop_v->type == DSM_JSON_STRING ? stop_v : stop_v->items[i]); if (!stops[i]) { error_response(fd, 400, "stop must contain strings"); goto done; } } }
    reused = common_prefix(s->cached, s->cached_len, tokens.ids, tokens.len);
    /* The cached logits follow the last generated token, not the last prompt
       token. Re-evaluate that prompt token when the entire prompt is reused. */
    if (reused == tokens.len && reused) --reused;
    if (s->use_metal && !dsm_metal_truncate(s->metal, (uint32_t)reused)) { error_response(fd, 500, "cache state error"); goto done; }
    if (!s->use_metal && !dsm_forward_truncate(s->forward, (uint32_t)reused)) { error_response(fd, 500, "cache state error"); goto done; }
    double prefill_started = now(); for (size_t i = reused; i < tokens.len; ++i) if (!(s->use_metal ? dsm_metal_token(s->metal, tokens.ids[i], s->logits) : dsm_forward_token(s->forward, tokens.ids[i], s->logits))) { error_response(fd, 500, "prompt inference failed"); goto done; } double prefill_elapsed = now() - prefill_started;
    char request_id[64]; snprintf(request_id, sizeof(request_id), "chatcmpl-%lx", (unsigned long)time(NULL)); if (stream && !send_all(fd, "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nConnection: close\r\n\r\n", 91)) goto done;
    dsm_sampler sampler; dsm_sampler_init(&sampler, temp, top_p, 1); double decode_started = now(); int finish_length = 1;
    for (int i = 0; i < max_tokens; ++i) { int32_t id = dsm_sample(&sampler, s->logits, s->model.vocab); string piece = {0}; if (!token_text(s->tokenizer, id, &piece) || !(s->use_metal ? dsm_metal_token(s->metal, id, s->logits) : dsm_forward_token(s->forward, id, s->logits))) { free(piece.data); break; } if (generated_len == generated_cap) { size_t cap = generated_cap ? generated_cap * 2 : 32; int32_t *p = realloc(generated, cap * sizeof(*p)); if (!p) { free(piece.data); break; } generated = p; generated_cap = cap; } generated[generated_len++] = id; if (!append(&output, piece.data, piece.len) || !append(&pending, piece.data, piece.len) || output.len > DSM_MAX_OUTPUT) { free(piece.data); break; } free(piece.data); size_t stop = stop_at(output.data, stops, stop_count); if (stop != SIZE_MAX) { output.len = stop; output.data[stop] = '\0'; finish_length = 0; break; } size_t ready = utf8_complete(pending.data, pending.len); if (stream && ready) { char saved = pending.data[ready]; pending.data[ready] = '\0'; int ok = sse_chunk(fd, request_id, pending.data, NULL); pending.data[ready] = saved; if (!ok) goto logged; memmove(pending.data, pending.data + ready, pending.len - ready); pending.len -= ready; pending.data[pending.len] = '\0'; } }
    if (stream && pending.len && !sse_chunk(fd, request_id, pending.data, NULL)) goto logged; if (stream) { if (!sse_chunk(fd, request_id, NULL, finish_length ? "length" : "stop") || !send_all(fd, LIT("data: [DONE]\n\n"))) goto logged; } else { string body = {0}; append(&body, LIT("{\"id\":\"")); append(&body, request_id, strlen(request_id)); append(&body, LIT("\",\"object\":\"chat.completion\",\"choices\":[{\"index\":0,\"message\":{\"role\":\"assistant\",\"content\":")); json_string(&body, output.data ? output.data : ""); appendf(&body, "},\"finish_reason\":\"%s\"}],\"usage\":{\"prompt_tokens\":%zu,\"completion_tokens\":%zu,\"total_tokens\":%zu}}", finish_length ? "length" : "stop", tokens.len, generated_len, tokens.len + generated_len); response(fd, 200, "application/json", body.data); free(body.data); }
logged: { double elapsed = now() - decode_started; fprintf(stderr, "dsm: prompt tokens %zu, reused tokens %zu, prefill %.2f tok/s, decode %.2f tok/s\n", tokens.len, reused, (tokens.len - reused) / (prefill_elapsed > 0 ? prefill_elapsed : 1e-9), generated_len / (elapsed > 0 ? elapsed : 1e-9)); cache_tokens(s, &tokens, generated, generated_len); }
done: for (size_t i = 0; i < stop_count; ++i) free(stops[i]); free(stops); free(generated); dsm_tokens_free(&tokens); free(prompt.data); free(output.data); free(pending.data); return 1;
}
static int read_request(int fd, char **method, char **path, char **body) { string request = {0}; char buffer[8192]; size_t header_len = 0, content_len = 0; for (;;) { ssize_t n = recv(fd, buffer, sizeof(buffer), 0); if (n <= 0 || !append(&request, buffer, (size_t)n) || request.len > DSM_MAX_BODY + 65536) goto bad; char *end = strstr(request.data, "\r\n\r\n"); if (!end) continue; header_len = (size_t)(end + 4 - request.data); char request_method[16], request_path[2048]; if (sscanf(request.data, "%15s %2047s", request_method, request_path) != 2) goto bad; *method = strdup(request_method); *path = strdup(request_path); if (!*method || !*path) goto bad; const char *cl = strcasestr(request.data, "\r\nContent-Length:"); if (!cl && !strcmp(*method, "POST")) goto bad; if (cl) { char *number_end; unsigned long parsed = strtoul(cl + 17, &number_end, 10); if (number_end == cl + 17) goto bad; content_len = (size_t)parsed; } if (content_len > DSM_MAX_BODY) { free(request.data); return -1; } while (request.len < header_len + content_len) { n = recv(fd, buffer, sizeof(buffer), 0); if (n <= 0 || !append(&request, buffer, (size_t)n)) goto bad; } *body = malloc(content_len + 1); if (!*body) goto bad; memcpy(*body, request.data + header_len, content_len); (*body)[content_len] = '\0'; free(request.data); return 1; } bad: free(request.data); free(*method); free(*path); *method = *path = NULL; return 0; }
static void handle(server *s, int fd) { char *method = NULL, *path = NULL, *body = NULL; int read = read_request(fd, &method, &path, &body); if (read < 0) error_response(fd, 413, "request body exceeds 8 MB"); else if (!read) error_response(fd, 400, "invalid HTTP request"); else if (!strcmp(method, "GET") && !strcmp(path, "/v1/models")) { string out = {0}; append(&out, LIT("{\"object\":\"list\",\"data\":[{\"id\":")); json_string(&out, s->model_id); append(&out, LIT(",\"object\":\"model\",\"owned_by\":\"dwarfstar-mini\"}]}")); response(fd, 200, "application/json", out.data); free(out.data); } else if (!strcmp(method, "POST") && !strcmp(path, "/v1/chat/completions")) { dsm_json *root = NULL; char error[128]; if (!dsm_json_parse(body, strlen(body), &root, error, sizeof(error)) || !root || root->type != DSM_JSON_OBJECT) error_response(fd, 400, error[0] ? error : "request must be a JSON object"); else generate(s, fd, root); dsm_json_free(root); } else error_response(fd, 404, "not found"); free(method); free(path); free(body); }
static int listener(const char *host, uint16_t port) { char port_text[16]; snprintf(port_text, sizeof(port_text), "%u", port); struct addrinfo hints = {0}, *result = NULL; hints.ai_family = AF_UNSPEC; hints.ai_socktype = SOCK_STREAM; hints.ai_flags = AI_PASSIVE; if (getaddrinfo(host, port_text, &hints, &result)) return -1; int fd = -1; for (struct addrinfo *it = result; it; it = it->ai_next) { fd = socket(it->ai_family, it->ai_socktype, it->ai_protocol); int yes = 1; if (fd >= 0 && setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes)) == 0 && bind(fd, it->ai_addr, it->ai_addrlen) == 0 && listen(fd, 8) == 0) break; if (fd >= 0) close(fd); fd = -1; } freeaddrinfo(result); return fd; }
int dsm_server_run(const char *model_path, const dsm_server_config *config) { server s = {0}; s.context = config->context; s.threads = config->threads; if (config->backend && strcmp(config->backend, "cpu") && strcmp(config->backend, "metal")) { fprintf(stderr, "dsm: unknown backend '%s'\n", config->backend); return 2; } s.use_metal = config->backend ? !strcmp(config->backend, "metal") : dsm_metal_available(); if (!dsm_model_open(&s.model, model_path)) { fprintf(stderr, "dsm: %s\n", s.model.error); return 1; } if (s.use_metal && s.model.is_moe) { fprintf(stderr, "dsm: MoE not yet supported on Metal, use --backend cpu\n"); dsm_model_close(&s.model); return 1; } if (!s.context) s.context = s.model.context; if (!dsm_tokenizer_init(&s.tokenizer, &s.model.gguf, s.model.error, sizeof(s.model.error)) || !(s.logits = malloc((size_t)s.model.vocab * sizeof(*s.logits)))) { fprintf(stderr, "dsm: server initialization failed\n"); dsm_tokenizer_free(s.tokenizer); dsm_model_close(&s.model); return 1; } if (s.use_metal) { char error[256]; if (!dsm_metal_init(&s.metal, &s.model, s.context, error, sizeof(error))) { fprintf(stderr, "dsm: Metal initialization failed: %s\n", error); free(s.logits); dsm_tokenizer_free(s.tokenizer); dsm_model_close(&s.model); return 1; } } else if (!dsm_forward_init(&s.forward, &s.model, s.context, s.threads)) { fprintf(stderr, "dsm: cannot allocate CPU forward state\n"); free(s.logits); dsm_tokenizer_free(s.tokenizer); dsm_model_close(&s.model); return 1; } const char *base = strrchr(model_path, '/'); base = base ? base + 1 : model_path; snprintf(s.model_id, sizeof(s.model_id), "%s", config->alias ? config->alias : base); char *suffix = strstr(s.model_id, ".gguf"); if (!config->alias && suffix && !suffix[5]) *suffix = '\0'; int fd = listener(config->host, config->port); if (fd < 0) { fprintf(stderr, "dsm: cannot listen on %s:%u\n", config->host, config->port); free(s.logits); dsm_metal_free(s.metal); dsm_forward_free(s.forward); dsm_tokenizer_free(s.tokenizer); dsm_model_close(&s.model); return 1; } signal(SIGPIPE, SIG_IGN); fprintf(stderr, "dsm: serving %s on http://%s:%u (%s)\n", s.model_id, config->host, config->port, s.use_metal ? "metal" : "cpu"); for (;;) { int client = accept(fd, NULL, NULL); if (client >= 0) { handle(&s, client); close(client); } else if (errno != EINTR) break; } close(fd); free(s.cached); free(s.logits); dsm_metal_free(s.metal); dsm_forward_free(s.forward); dsm_tokenizer_free(s.tokenizer); dsm_model_close(&s.model); return 0; }
